  hashMapSize: (m: FL8HashMap) => m.size(),
  hashMapKeys: (m: FL8HashMap) => m.keys(),
  hashMapValues: (m: FL8HashMap) => m.values(),
  hashMapToObject: (m: FL8HashMap) => m.toObject(),
  hashMapFromObject: (obj: Record<string, unknown>) => FL8HashMap.fromObject(obj),

  // Queue
  queue: () => new FL8Queue(),
  queueEnqueue: (q: FL8Queue, v: unknown) => { q.enqueue(v); return q; },
  queueDequeue: (q: FL8Queue) => q.dequeue(),
  queuePeek: (q: FL8Queue) => q.peek(),
  queueIsEmpty: (q: FL8Queue) => q.isEmpty(),
  queueSize: (q: FL8Queue) => q.size(),

  // Stack
  stack: () => new FL8Stack(),
  stackPush: (s: FL8Stack, v: unknown) => { s.push(v); return s; },
  stackPop: (s: FL8Stack) => s.pop(),
  stackPeek: (s: FL8Stack) => s.peek(),
  stackIsEmpty: (s: FL8Stack) => s.isEmpty(),
  stackSize: (s: FL8Stack) => s.size(),

  // PriorityQueue
  priorityQueue: () => new FL8PriorityQueue(),
  pqEnqueue: (pq: FL8PriorityQueue, v: unknown, p: number) => { pq.enqueue(v, p); return pq; },
  pqDequeue: (pq: FL8PriorityQueue) => pq.dequeue(),
  pqPeek: (pq: FL8PriorityQueue) => pq.peek(),
  pqIsEmpty: (pq: FL8PriorityQueue) => pq.isEmpty(),
  pqSize: (pq: FL8PriorityQueue) => pq.size(),

  // Set
  set: () => new FL8Set(),
  setAdd: (s: FL8Set, v: unknown) => { s.add(v); return s; },
  setHas: (s: FL8Set, v: unknown) => s.has(v),
  setDelete: (s: FL8Set, v: unknown) => s.delete(v),
  setSize: (s: FL8Set) => s.size(),
  setToArray: (s: FL8Set) => s.toArray(),
};

