    10→import { Trainer } from "../ml/trainer";
    11→import { CharTokenizer, BPETokenizer, makeNgramData } from "../ml/tokenizer";
    12→import { MultiHeadAttention, LayerNorm, positionalEncoding } from "../ml/attention";
    13→import { MiniGPT, TransformerBlock, Embedding, trainLM, GPTConfig } from "../ml/transformer";
    14→
    15→// ============================================================
    16→// RuntimeValue — 인터프리터가 다루는 값
    17→// ============================================================
    18→
    19→export type RuntimeValue =
    20→  | { tag: "number"; val: number }
    21→  | { tag: "bool"; val: boolean }
    22→  | { tag: "string"; val: string }
    23→  | { tag: "tensor"; data: number[]; shape: number[] }
    24→  | { tag: "autograd"; val: AutoValue }
    25→  | { tag: "array"; val: RuntimeValue[] }
    26→  | { tag: "fn"; params: string[]; body: Stmt[]; closure: Env }
    27→  | { tag: "builtin"; fn: (...args: RuntimeValue[]) => RuntimeValue }
    28→  | { tag: "null" };
    29→
    30→// ============================================================
    31→// Environment (스코프 체인)
    32→// ============================================================
    33→
    34→export class Env {
    35→  private vars: Map<string, RuntimeValue> = new Map();
    36→  constructor(public parent: Env | null = null) {}
    37→
    38→  get(name: string): RuntimeValue {
    39→    if (this.vars.has(name)) return this.vars.get(name)!;
    40→    if (this.parent) return this.parent.get(name);
    41→    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
    42→  }
    43→
    44→  set(name: string, val: RuntimeValue): void {
    45→    this.vars.set(name, val);
    46→  }
    47→
    48→  assign(name: string, val: RuntimeValue): void {
    49→    if (this.vars.has(name)) { this.vars.set(name, val); return; }
    50→    if (this.parent) { this.parent.assign(name, val); return; }
    51→    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
    52→  }
    53→}
    54→
    55→// ============================================================
    56→// 제어 흐름 시그널
    57→// ============================================================
    58→
    59→class ReturnSignal { constructor(public value: RuntimeValue) {} }
    60→class BreakSignal {}
    61→class ContinueSignal {}
    62→class RuntimeError extends Error { constructor(msg: string) { super(msg); } }
