});

test('FL8Stack: LIFO 순서 보장', () => {
  const s = new FL8Stack<string>();
  ['a', 'b', 'c'].forEach(x => s.push(x));
  const out: string[] = [];
  while (!s.isEmpty()) out.push(s.pop()!);
  assertEqual(out, ['c', 'b', 'a']);
});

