test('FL8LinkedList: pushFront / toArray', () => {
  const ll = new FL8LinkedList<number>();
  ll.pushFront(3); ll.pushFront(2); ll.pushFront(1);
  assertEqual(ll.toArray(), [1, 2, 3]);
});

