test('transaction: 롤백', () => {
  const db = new FL8Db();
  db.createTable('t', ['id', 'val']);
  db.insert('t', { val: 1 });
  db.transaction(d => {
    d.insert('t', { val: 2 });
    throw new Error('rollback!');
  });
