// FreeLang v8 ML — Phase 9 표준 라이브러리 테스트
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { FL8_FS } from '../src/stdlib/fs';
import { FL8_HTTP } from '../src/stdlib/http';
import { FL8_SQLITE, FL8Db } from '../src/stdlib/sqlite';
import {
  FL8HashMap, FL8Queue, FL8Stack, FL8PriorityQueue, FL8Set, FL8LinkedList,
  FL8_COLLECTIONS,
} from '../src/stdlib/collections';
import { Interpreter } from '../src/runtime/interpreter';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function assertEqual<T>(a: T, b: T, msg?: string) {
  const m = msg ?? `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`;
  if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(m);
}

// FL8 소스 실행 헬퍼
const interp = new Interpreter();
function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  return interp.run(program);
}

// ============================================================
// 1. 파일 시스템 (FL8_FS)
// ============================================================
console.log('\n── 파일 시스템 (FL8_FS) ──');

const TMP = path.join(os.tmpdir(), `fl8_test_${Date.now()}`);

test('fs_write: 파일 쓰기', () => {
  const ok = FL8_FS.write(path.join(TMP, 'hello.txt'), 'Hello, FreeLang!');
  assert(ok, 'write 실패');
});

test('fs_read: 파일 읽기', () => {
  const content = FL8_FS.read(path.join(TMP, 'hello.txt'));
  assert(content === 'Hello, FreeLang!', `내용 불일치: ${content}`);
});

test('fs_exists: 존재 확인', () => {
  assert(FL8_FS.exists(path.join(TMP, 'hello.txt')), '파일이 존재해야 함');
  assert(!FL8_FS.exists(path.join(TMP, 'none.txt')), '없는 파일은 false');
});

test('fs_append: 내용 추가', () => {
  const fp = path.join(TMP, 'append.txt');
  FL8_FS.write(fp, 'Line1\n');
  FL8_FS.append(fp, 'Line2\n');
  const c = FL8_FS.read(fp)!;
  assert(c.includes('Line1') && c.includes('Line2'), '추가 실패');
});

test('fs_ls: 디렉토리 목록', () => {
  const files = FL8_FS.ls(TMP);
  assert(Array.isArray(files) && files.length >= 1, `목록 오류: ${files}`);
});

test('fs_mkdir: 디렉토리 생성', () => {
  const ok = FL8_FS.mkdir(path.join(TMP, 'subdir'));
  assert(ok, 'mkdir 실패');
  assert(FL8_FS.exists(path.join(TMP, 'subdir')), '디렉토리 없음');
});

test('fs_read_json / fs_write_json: JSON 파일', () => {
  const fp = path.join(TMP, 'data.json');
  FL8_FS.writeJson(fp, { name: 'fl8', version: 9 });
  const data = FL8_FS.readJson(fp) as any;
  assert(data?.name === 'fl8' && data?.version === 9, 'JSON 불일치');
});

test('fs_join: 경로 조합', () => {
  const p = FL8_FS.join('/tmp', 'a', 'b.txt');
  assert(p === '/tmp/a/b.txt', `경로: ${p}`);
});

test('fs_delete: 파일 삭제', () => {
  const fp = path.join(TMP, 'del.txt');
  FL8_FS.write(fp, 'bye');
  FL8_FS.delete(fp);
  assert(!FL8_FS.exists(fp), '삭제 실패');
});

// ============================================================
// 2. SQLite 인메모리 DB (FL8Db)
// ============================================================
console.log('\n── SQLite 인메모리 DB ──');

test('createTable: 테이블 생성', () => {
  const db = new FL8Db();
  db.createTable('users', ['id', 'name', 'age']);
  assert(db.tableExists('users'), '테이블 없음');
});

test('insert / select: 삽입 및 조회', () => {
  const db = new FL8Db();
  db.createTable('users', ['id', 'name', 'age']);
  const r = db.insert('users', { name: 'Kim', age: 30 });
  assert(r.lastInsertId === 1, 'lastInsertId 오류');
  const rows = db.select('users').rows;
  assert(rows.length === 1 && rows[0].name === 'Kim', '조회 실패');
});

test('insertMany: 다중 삽입', () => {
  const db = new FL8Db();
  db.createTable('items', ['id', 'label']);
  db.insertMany('items', [{ label: 'A' }, { label: 'B' }, { label: 'C' }]);
  assert(db.count('items') === 3, '카운트 오류');
});

test('select with where: 조건 조회', () => {
  const db = new FL8Db();
  db.createTable('products', ['id', 'category', 'price']);
  db.insert('products', { category: 'fruit', price: 100 });
  db.insert('products', { category: 'veggie', price: 50 });
  db.insert('products', { category: 'fruit', price: 200 });
  const rows = db.select('products', { category: 'fruit' }).rows;
  assert(rows.length === 2, `조건 조회 오류: ${rows.length}`);
});

test('update: 레코드 수정', () => {
  const db = new FL8Db();
  db.createTable('kv', ['id', 'key', 'value']);
  db.insert('kv', { key: 'x', value: 1 });
  db.update('kv', { value: 99 }, { key: 'x' });
  const rows = db.select('kv', { key: 'x' }).rows;
  assert(rows[0].value === 99, '업데이트 실패');
});

test('delete: 레코드 삭제', () => {
  const db = new FL8Db();
  db.createTable('log', ['id', 'msg']);
  db.insert('log', { msg: 'a' });
  db.insert('log', { msg: 'b' });
  db.delete('log', { msg: 'a' });
  assert(db.count('log') === 1, '삭제 오류');
});

test('transaction: 롤백', () => {
  const db = new FL8Db();
  db.createTable('t', ['id', 'val']);
  db.insert('t', { val: 1 });
  db.transaction(d => {
    d.insert('t', { val: 2 });
    throw new Error('rollback!');
  });
  assert(db.count('t') === 1, '롤백 실패');
});

test('transaction: 커밋', () => {
  const db = new FL8Db();
  db.createTable('t', ['id', 'val']);
  db.transaction(d => { d.insert('t', { val: 42 }); });
  assert(db.count('t') === 1, '커밋 실패');
});

test('query(SQL): SELECT', () => {
  const db = new FL8Db();
  db.query('CREATE TABLE animals (id, name, legs)');
  db.query("INSERT INTO animals (name, legs) VALUES ('cat', 4)");
  db.query("INSERT INTO animals (name, legs) VALUES ('bird', 2)");
  const r = db.query('SELECT * FROM animals');
  assert(r.rows.length === 2, `SQL SELECT 오류: ${r.rows.length}`);
});

test('query(SQL): WHERE 조건', () => {
  const db = new FL8Db();
  db.query('CREATE TABLE nums (id, val)');
  db.query("INSERT INTO nums (val) VALUES (10)");
  db.query("INSERT INTO nums (val) VALUES (20)");
  const r = db.query('SELECT * FROM nums WHERE val=20');
  assert(r.rows.length === 1 && r.rows[0].val === 20, 'WHERE 오류');
});

test('query(SQL): UPDATE', () => {
  const db = new FL8Db();
  db.query('CREATE TABLE kv (id, k, v)');
  db.query("INSERT INTO kv (k, v) VALUES ('a', 1)");
  db.query("UPDATE kv SET v=99 WHERE k='a'");
  const r = db.query("SELECT * FROM kv WHERE k='a'");
  assert(r.rows[0].v === 99, 'SQL UPDATE 오류');
});

test('query(SQL): DELETE', () => {
  const db = new FL8Db();
  db.query('CREATE TABLE items (id, name)');
  db.query("INSERT INTO items (name) VALUES ('x')");
  db.query("INSERT INTO items (name) VALUES ('y')");
  db.query("DELETE FROM items WHERE name='x'");
  const r = db.query('SELECT * FROM items');
  assert(r.rows.length === 1 && r.rows[0].name === 'y', 'SQL DELETE 오류');
});

test('save / load: JSON 파일 영속화', () => {
  const fp = path.join(TMP, 'db.json');
  const db = new FL8Db(fp);
  db.createTable('memo', ['id', 'text']);
  db.insert('memo', { text: 'hello' });
  db.save();

  const db2 = new FL8Db(fp);
  assert(db2.count('memo') === 1, '로드 실패');
  fs.unlinkSync(fp);
});

// ── FL8_SQLITE 핸들 API ────────────────────────────────────────
test('FL8_SQLITE: inMemory + createTable + insert + select + count', () => {
  const h = FL8_SQLITE.inMemory();
  FL8_SQLITE.createTable(h, 'users', ['id', 'name']);
  FL8_SQLITE.insert(h, 'users', { name: 'Alice' });
  FL8_SQLITE.insert(h, 'users', { name: 'Bob' });
  const rows = FL8_SQLITE.select(h, 'users');
  assert(rows.length === 2, '선택 오류');
  assert(FL8_SQLITE.count(h, 'users') === 2, '카운트 오류');
  FL8_SQLITE.close(h);
});

// ============================================================
// 3. Collections
// ============================================================
console.log('\n── Collections ──');

// HashMap
test('FL8HashMap: set / get / has / delete / size', () => {
  const m = new FL8HashMap<string, number>();
  m.set('a', 1).set('b', 2).set('c', 3);
  assert(m.get('a') === 1, 'get a');
  assert(m.has('b'), 'has b');
  assert(m.size() === 3, 'size 3');
  m.delete('b');
  assert(!m.has('b'), 'b 삭제됨');
  assert(m.size() === 2, 'size 2');
});

test('FL8HashMap: getOr', () => {
  const m = new FL8HashMap<string, number>();
  m.set('x', 10);
  assert(m.getOr('x', 0) === 10, 'getOr existing');
  assert(m.getOr('y', 99) === 99, 'getOr default');
});

test('FL8HashMap: keys / values / entries', () => {
  const m = new FL8HashMap<string, number>();
  m.set('a', 1).set('b', 2);
  const keys = m.keys().sort();
  const vals = m.values().sort((a, b) => a - b);
  assertEqual(keys, ['a', 'b']);
  assertEqual(vals, [1, 2]);
  assert(m.entries().length === 2, 'entries 길이');
});

test('FL8HashMap: map / filter', () => {
  const m = new FL8HashMap<string, number>();
  m.set('a', 1).set('b', 2).set('c', 3);
  const doubled = m.map(v => v * 2);
  assert(doubled.get('a') === 2 && doubled.get('b') === 4, 'map');
  const even = m.filter(v => v % 2 === 0);
  assert(even.size() === 1 && even.has('b'), 'filter');
});

test('FL8HashMap: toObject / fromObject', () => {
  const obj = { x: 10, y: 20 };
  const m = FL8HashMap.fromObject(obj);
  assert(m.get('x') === 10, 'fromObject');
  const back = m.toObject();
  assertEqual(back, obj);
});

// Queue
test('FL8Queue: enqueue / dequeue / peek / isEmpty / size', () => {
  const q = new FL8Queue<number>();
  assert(q.isEmpty(), '처음 빈 상태');
  q.enqueue(1); q.enqueue(2); q.enqueue(3);
  assert(q.size() === 3, 'size 3');
  assert(q.peek() === 1, 'peek 1');
  assert(q.dequeue() === 1, 'dequeue 1');
  assert(q.dequeue() === 2, 'dequeue 2');
  assert(q.size() === 1, 'size 1');
});

test('FL8Queue: FIFO 순서 보장', () => {
  const q = new FL8Queue<string>();
  ['a', 'b', 'c', 'd'].forEach(x => q.enqueue(x));
  const out: string[] = [];
  while (!q.isEmpty()) out.push(q.dequeue()!);
  assertEqual(out, ['a', 'b', 'c', 'd']);
});

test('FL8Queue: 대용량 dequeue 압축', () => {
  const q = new FL8Queue<number>();
  for (let i = 0; i < 200; i++) q.enqueue(i);
  for (let i = 0; i < 150; i++) q.dequeue();
  assert(q.size() === 50, '압축 후 크기');
  assert(q.peek() === 150, '압축 후 peek');
});

// Stack
test('FL8Stack: push / pop / peek / isEmpty / size', () => {
  const s = new FL8Stack<number>();
  assert(s.isEmpty(), '처음 빈 상태');
  s.push(10); s.push(20); s.push(30);
  assert(s.size() === 3, 'size 3');
  assert(s.peek() === 30, 'peek 30');
  assert(s.pop() === 30, 'pop 30');
  assert(s.pop() === 20, 'pop 20');
  assert(s.size() === 1, 'size 1');
});

test('FL8Stack: LIFO 순서 보장', () => {
  const s = new FL8Stack<string>();
  ['a', 'b', 'c'].forEach(x => s.push(x));
  const out: string[] = [];
  while (!s.isEmpty()) out.push(s.pop()!);
  assertEqual(out, ['c', 'b', 'a']);
});

// PriorityQueue
test('FL8PriorityQueue: enqueue / dequeue (min-heap)', () => {
  const pq = new FL8PriorityQueue<string>();
  pq.enqueue('low', 10);
  pq.enqueue('high', 1);
  pq.enqueue('mid', 5);
  assertEqual(pq.dequeue(), 'high');
  assertEqual(pq.dequeue(), 'mid');
  assertEqual(pq.dequeue(), 'low');
});

test('FL8PriorityQueue: peek / peekPriority', () => {
  const pq = new FL8PriorityQueue<number>();
  pq.enqueue(99, 3);
  pq.enqueue(42, 1);
  assert(pq.peek() === 42, 'peek');
  assert(pq.peekPriority() === 1, 'peekPriority');
});

test('FL8PriorityQueue: isEmpty / size / clear', () => {
  const pq = new FL8PriorityQueue<string>();
  assert(pq.isEmpty(), '처음 빈 상태');
  pq.enqueue('a', 1); pq.enqueue('b', 2);
  assert(pq.size() === 2, 'size 2');
  pq.clear();
  assert(pq.isEmpty(), '클리어 후 빈 상태');
});

// Set
test('FL8Set: add / has / delete / size', () => {
  const s = new FL8Set<number>();
  s.add(1).add(2).add(3).add(2);  // 중복 2
  assert(s.size() === 3, '중복 제거');
  assert(s.has(2), 'has 2');
  s.delete(2);
  assert(!s.has(2), '삭제됨');
});

test('FL8Set: union / intersection / difference', () => {
  const a = new FL8Set<number>();
  const b = new FL8Set<number>();
  [1, 2, 3].forEach(x => a.add(x));
  [2, 3, 4].forEach(x => b.add(x));
  assertEqual(a.union(b).toArray().sort((x, y) => x - y), [1, 2, 3, 4]);
  assertEqual(a.intersection(b).toArray().sort((x, y) => x - y), [2, 3]);
  assertEqual(a.difference(b).toArray(), [1]);
});

// LinkedList
test('FL8LinkedList: pushBack / popFront / peekFront', () => {
  const ll = new FL8LinkedList<number>();
  ll.pushBack(1); ll.pushBack(2); ll.pushBack(3);
  assert(ll.peekFront() === 1, 'peekFront');
  assert(ll.popFront() === 1, 'popFront 1');
  assert(ll.size() === 2, 'size 2');
});

test('FL8LinkedList: pushFront / toArray', () => {
  const ll = new FL8LinkedList<number>();
  ll.pushFront(3); ll.pushFront(2); ll.pushFront(1);
  assertEqual(ll.toArray(), [1, 2, 3]);
});

// ============================================================
// 4. 인터프리터 통합 (stdlib 내장 함수)
