  const fp = path.join(TMP, 'interp_test.txt').replace(/\\/g, '/');
  const dir = TMP.replace(/\\/g, '/');
  const interp2 = new Interpreter();
  const { tokens } = new Lexer(`
    let exists = fs_exists("${fp}")
    let files = fs_ls("${dir}")
  `).tokenize();
  const { program } = new Parser(tokens).parse();
  interp2.run(program);
});

test('db_memory / db_create_table / db_insert / db_count: 인터프리터', () => {
  const interp2 = new Interpreter();
  const { tokens } = new Lexer(`
    let h = db_memory()
    db_create_table(h, "notes", "id", "text")
    db_insert(h, "notes", "text", "hello")
    db_insert(h, "notes", "text", "world")
