  [1, 2, 3].forEach(x => a.add(x));
  [2, 3, 4].forEach(x => b.add(x));
  assertEqual(a.union(b).toArray().sort((x, y) => x - y), [1, 2, 3, 4]);
  assertEqual(a.intersection(b).toArray().sort((x, y) => x - y), [2, 3]);
  assertEqual(a.difference(b).toArray(), [1]);
});

