          if ch == 40 { push(result, 5) i = i + 1 }  // '('
          if ch == 41 { push(result, 6) i = i + 1 }  // ')'
          if ch == 59 { push(result, 3) i = i + 1 }  // ';'
        }
      }
    }
  }

  return result
}

