// FreeLang v8 ML — Self-Hosting Phase 10
// FL8로 작성된 미니 산술 인터프리터
//   입력: 숫자 토큰 배열 + 연산자 코드 배열
//   연산자 코드: 0=+  1=-  2=*  3=/
//
// 표현식 문법:
//   expr   = term (( '+' | '-' ) term)*
//   term   = factor (( '*' | '/' ) factor)*
//   factor = NUMBER | '(' expr ')'
//
// 상태를 배열 [pos] 로 관리 (FL8는 레퍼런스 전달)

// ─── 파서 상태 ───────────────────────────────────────────────
// state[0] = 현재 위치

fn make_state() -> [f32] {
  return [0]
}

fn pos_get(state: [f32]) -> f32 {
  return state[0]
}

fn pos_inc(state: [f32]) -> f32 {
  state[0] = state[0] + 1
  return state[0]
}

// ─── 토큰 스트림 ─────────────────────────────────────────────
// tok_types: 1=NUM 3=OP 5=LPAREN 6=RPAREN
// tok_vals : NUM이면 숫자값, OP이면 0(+) 1(-) 2(*) 3(/)

fn tok_type(tok_types: [f32], state: [f32]) -> f32 {
  let p = pos_get(state)
  if p >= len(tok_types) { return 0 }  // EOF
  return tok_types[p]
}

fn tok_val(tok_vals: [f32], state: [f32]) -> f32 {
  let p = pos_get(state)
  if p >= len(tok_vals) { return 0 }
  return tok_vals[p]
}

fn consume(state: [f32]) -> f32 {
  pos_inc(state)
  return 0
}

// ─── 재귀 하강 파서 겸 평가기 ─────────────────────────────────

fn parse_expr(tok_types: [f32], tok_vals: [f32], state: [f32]) -> f32
fn parse_term(tok_types: [f32], tok_vals: [f32], state: [f32]) -> f32
fn parse_factor(tok_types: [f32], tok_vals: [f32], state: [f32]) -> f32

fn parse_factor(tok_types: [f32], tok_vals: [f32], state: [f32]) -> f32 {
  let tt = tok_type(tok_types, state)
  if tt == 1 {
    // NUM: 값 소비 후 반환
    let v = tok_val(tok_vals, state)
    consume(state)
    return v
  }
  if tt == 5 {
    // '(' expr ')'
    consume(state)  // (
    let v2 = parse_expr(tok_types, tok_vals, state)
    consume(state)  // )
    return v2
  }
  return 0
}

fn parse_term(tok_types: [f32], tok_vals: [f32], state: [f32]) -> f32 {
  let left = parse_factor(tok_types, tok_vals, state)
  let cont = 1
  while cont == 1 {
    let tt = tok_type(tok_types, state)
    if tt != 3 {
      cont = 0
    } else {
      let op = tok_val(tok_vals, state)
      if op == 2 {
        // '*'
        consume(state)
        let right = parse_factor(tok_types, tok_vals, state)
        left = left * right
      } else {
        if op == 3 {
          // '/'
          consume(state)
          let right2 = parse_factor(tok_types, tok_vals, state)
          left = left / right2
        } else {
          cont = 0
        }
      }
    }
  }
  return left
}

fn parse_expr(tok_types: [f32], tok_vals: [f32], state: [f32]) -> f32 {
  let left = parse_term(tok_types, tok_vals, state)
  let cont = 1
  while cont == 1 {
    let tt = tok_type(tok_types, state)
    if tt != 3 {
      cont = 0
    } else {
      let op = tok_val(tok_vals, state)
      if op == 0 {
        // '+'
        consume(state)
        let right = parse_term(tok_types, tok_vals, state)
        left = left + right
      } else {
        if op == 1 {
          // '-'
          consume(state)
          let right2 = parse_term(tok_types, tok_vals, state)
          left = left - right2
        } else {
          cont = 0
        }
      }
    }
  }
  return left
}

// ─── 공개 API: eval_expr(tok_types, tok_vals) → 결과값 ────────

fn eval_expr(tok_types: [f32], tok_vals: [f32]) -> f32 {
  let state = make_state()
  return parse_expr(tok_types, tok_vals, state)
}

// ─── 검증 헬퍼 ────────────────────────────────────────────────

fn check(label: str, got: f32, want: f32) -> f32 {
  if got == want {
    print("  PASS:", label, "=", got)
    return 1
  }
  print("  FAIL:", label, "got", got, "want", want)
  return 0
}

// ─── 테스트 ───────────────────────────────────────────────────

print("=== FL8 Self-Hosting: 산술 평가기 ===")
print("")

// 테스트 1: 3 + 4  → 7
// tok_types: [1, 3, 1]   (NUM OP NUM)
// tok_vals:  [3, 0, 4]   (3  +  4)
let r1 = eval_expr([1, 3, 1], [3, 0, 4])
let ok1 = check("3 + 4", r1, 7)

// 테스트 2: 10 - 3  → 7
let r2 = eval_expr([1, 3, 1], [10, 1, 3])
let ok2 = check("10 - 3", r2, 7)

// 테스트 3: 6 * 7  → 42
let r3 = eval_expr([1, 3, 1], [6, 2, 7])
let ok3 = check("6 * 7", r3, 42)

// 테스트 4: 15 / 3  → 5
let r4 = eval_expr([1, 3, 1], [15, 3, 3])
let ok4 = check("15 / 3", r4, 5)

// 테스트 5: 2 + 3 * 4  → 14  (우선순위: * 먼저)
// [NUM, OP(+), NUM, OP(*), NUM]
let r5 = eval_expr([1, 3, 1, 3, 1], [2, 0, 3, 2, 4])
let ok5 = check("2 + 3 * 4", r5, 14)

// 테스트 6: (2 + 3) * 4  → 20  (괄호)
// [LPAREN, NUM, OP(+), NUM, RPAREN, OP(*), NUM]
let r6 = eval_expr([5, 1, 3, 1, 6, 3, 1], [0, 2, 0, 3, 0, 2, 4])
let ok6 = check("(2 + 3) * 4", r6, 20)

// 테스트 7: 10 - 2 - 3  → 5  (좌결합)
let r7 = eval_expr([1, 3, 1, 3, 1], [10, 1, 2, 1, 3])
let ok7 = check("10 - 2 - 3", r7, 5)

// 테스트 8: 100 / 5 / 4  → 5  (좌결합)
let r8 = eval_expr([1, 3, 1, 3, 1], [100, 3, 5, 3, 4])
let ok8 = check("100 / 5 / 4", r8, 5)

// 테스트 9: (1 + 2) * (3 + 4)  → 21
// [( NUM + NUM ) * ( NUM + NUM )]
let r9 = eval_expr(
  [5, 1, 3, 1, 6, 3, 5, 1, 3, 1, 6],
  [0, 1, 0, 2, 0, 2, 0, 3, 0, 4, 0]
)
let ok9 = check("(1+2)*(3+4)", r9, 21)

// 테스트 10: 2 * 3 + 4 * 5  → 26
let r10 = eval_expr([1, 3, 1, 3, 1, 3, 1], [2, 2, 3, 0, 4, 2, 5])
let ok10 = check("2*3 + 4*5", r10, 26)

print("")
let total = ok1 + ok2 + ok3 + ok4 + ok5 + ok6 + ok7 + ok8 + ok9 + ok10
print("산술 평가기 결과:", total, "/ 10")

