//
// 배열 인터리빙: [type0, val0, type1, val1, ...]

// ─── 파서 상태 [pos] ──────────────────────────────────────────

fn st_new() -> [f32] { return [0] }
fn st_pos(s: [f32]) -> f32 { return s[0] }
fn st_next(s: [f32]) -> f32 { s[0] = s[0] + 2  return 0 }

fn cur_type(tokens: [f32], s: [f32]) -> f32 {
  let p = st_pos(s)
  if p >= len(tokens) { return 0 }
  return tokens[p]
}

fn cur_val(tokens: [f32], s: [f32]) -> f32 {
  let p = st_pos(s)
  if p + 1 >= len(tokens) { return 0 }
  return tokens[p + 1]
}

// ─── 계산 스택 기반 파서 ─────────────────────────────────────
// 연산자 우선순위: * / 가 + - 보다 높음
//
// 알고리즘: shunting-yard (연산자 스택 + 값 스택)
// prec[op]: 0(+)→1  1(-)→1  2(*)→2  3(/)→2

fn op_prec(op: f32) -> f32 {
  if op == 0 { return 1 }  // +
  if op == 1 { return 1 }  // -
  if op == 2 { return 2 }  // *
  if op == 3 { return 2 }  // /
  return 0
}

fn apply_op(op: f32, a: f32, b: f32) -> f32 {
  if op == 0 { return a + b }
  if op == 1 { return a - b }
  if op == 2 { return a * b }
  if op == 3 { return a / b }
  return 0
}

// eval_tokens: shunting-yard 방식 평가
fn eval_tokens(tokens: [f32]) -> f32 {
  let vals = []    // 값 스택
  let ops  = []    // 연산자 스택
  let s = st_new()

  let running = 1
  while running == 1 {
    let tt = cur_type(tokens, s)

    if tt == 0 {
      // EOF
      running = 0
    } else {
      if tt == 1 {
        // NUM: 값 스택에 푸시
        push(vals, cur_val(tokens, s))
        st_next(s)
      } else {
        if tt == 5 {
          // LPAREN: 연산자 스택에 -1 (sentinel)
          push(ops, -1)
          st_next(s)
        } else {
          if tt == 6 {
            // RPAREN: sentinel까지 연산자 처리
            let cont_rp = 1
            while cont_rp == 1 {
              if len(ops) == 0 {
                cont_rp = 0
              } else {
                let top_op = ops[len(ops) - 1]
                if top_op == -1 {
                  pop(ops)
                  cont_rp = 0
                } else {
                  pop(ops)
                  let b = pop(vals)
                  let a = pop(vals)
                  push(vals, apply_op(top_op, a, b))
                }
              }
            }
            st_next(s)
          } else {
            if tt == 3 {
              // OP: 현재 연산자보다 우선순위 높은 것 먼저 처리
              let cur_op = cur_val(tokens, s)
              let cont_op = 1
              while cont_op == 1 {
                if len(ops) == 0 {
                  cont_op = 0
                } else {
                  let top_op2 = ops[len(ops) - 1]
                  if top_op2 == -1 {
                    cont_op = 0
                  } else {
                    if op_prec(top_op2) >= op_prec(cur_op) {
                      pop(ops)
                      let b2 = pop(vals)
                      let a2 = pop(vals)
                      push(vals, apply_op(top_op2, a2, b2))
                    } else {
                      cont_op = 0
                    }
                  }
                }
              }
              push(ops, cur_op)
              st_next(s)
            } else {
              running = 0
            }
          }
        }
      }
    }
  }

  // 남은 연산자 처리
  let cont_end = 1
  while cont_end == 1 {
    if len(ops) == 0 {
      cont_end = 0
    } else {
      let op_end = pop(ops)
      if op_end != -1 {
        let b3 = pop(vals)
        let a3 = pop(vals)
        push(vals, apply_op(op_end, a3, b3))
      }
    }
  }

  if len(vals) == 0 { return 0 }
  return vals[0]
}

