// PUSH 3, PUSH 4, ADD, PRINT, HALT
let p2 = [0,3, 0,4, 3, 10, 11]
let o2 = run_vm(p2)
let ok2 = check_arr("3+4 PRINT", o2, [7])

// 테스트 3: 변수 x=10, y=5, x*y
// PUSH 10, STORE 0(x), PUSH 5, STORE 1(y)
// LOAD 0, LOAD 1, MUL, PRINT, HALT
let p3 = [0,10, 2,0, 0,5, 2,1, 1,0, 1,1, 5, 10, 11]
let o3 = run_vm(p3)
let ok3 = check_arr("x=10,y=5,x*y", o3, [50])

// 테스트 4: if문 (조건 참)
// x=3, if x < 5: print(1)
// PUSH 3, STORE 0
// LOAD 0, PUSH 5, CMP_LT
// JMP_IF_FALSE 3  (false면 3칸 점프)
// PUSH 1, PRINT
// HALT
let p4 = [0,3, 2,0, 1,0, 0,5, 8, 7,3, 0,1, 10, 11]
let o4 = run_vm(p4)
let ok4 = check_arr("if x<5: print(1)", o4, [1])

// 테스트 5: if문 (조건 거짓)
// x=10, if x < 5: print(1)
// JMP_IF_FALSE → 점프 → PRINT 스킵
let p5 = [0,10, 2,0, 1,0, 0,5, 8, 7,3, 0,1, 10, 11]
let o5 = run_vm(p5)
let ok5 = check_arr("if 10<5 (거짓)", o5, [])

// 테스트 6: 루프 (1+2+3+4+5 = 15)
// sum=0, i=1
// loop: if i>5 goto end
//   sum = sum + i
//   i = i + 1
//   goto loop
// print sum
//
// 위치별 명령어 (ip 기준):
//  0: PUSH 0
//  2: STORE 0  (sum=0)
//  4: PUSH 1
//  6: STORE 1  (i=1)
// --- 루프 시작 (ip=8) ---
//  8: LOAD 1   (i)
// 10: PUSH 5
// 12: CMP_GT   (i > 5?)
// 13: JMP_IF_FALSE 2  (거짓이면 +2→ip=17 → 루프 본체)
// 15: 점프 후 → HALT(ip=23)
// 17: LOAD 0  (sum)
// 19: LOAD 1  (i)
// 21: ADD
// 22: STORE 0 (sum)
// 24: LOAD 1  (i)
// 26: PUSH 1
// 28: ADD
// 29: STORE 1 (i)
// 31: JMP_IF_FALSE 0 → 쓸 수 없음, 대신 PUSH 1, JMP_IF_FALSE -24
//
// 단순화: PUSH 1(항상참) + JMP_IF_FALSE 와 음수오프셋 대신
// goto는 항상참 조건 + 음수 오프셋으로 구현
// JMP_IF_FALSE offset: ip += offset (offset 가 음수면 역방향)
// offset = -26 → 뒤로 26 칸

// 명령어 배열 (인덱스 계산):
// [0]PUSH[1]0  [2]STORE[3]0
// [4]PUSH[5]1  [6]STORE[7]1
// [8]LOAD[9]1  [10]PUSH[11]5  [12]CMP_GT
// [13]JMP_IF_FALSE[14]8       (false→ip+8=21: 루프 본체)
// [15]PUSH[16]1  [17]JMP_IF_FALSE[18]0   (항상 false=0? 아님)
// → goto end: PUSH 0, JMP_IF_FALSE 건너뜀 → 그냥 HALT 로 점프
// → 더 단순: 조건 참이면 (CMP_GT=1) JMP_IF_FALSE는 동작 안 함 → 다음 명령 실행
//            조건 거짓이면 (CMP_GT=0) JMP_IF_FALSE → offset 만큼 점프
// [13]JMP_IF_FALSE 8 → ip=13+2+8=23: 루프 본체
// [15]HALT (루프 빠져나옴)
// [17]LOAD[18]0  [19]LOAD[20]1  [21]ADD
// [22]STORE[23]0
// [24]LOAD[25]1  [26]PUSH[27]1  [28]ADD
// [29]STORE[30]1
// [31]PUSH[32]1  [33]JMP_IF_FALSE[34]? (항상 1이라 건너뜀 → 안 동작)
// 뒤로 돌아가려면 음수: ip=35 + offset → ip=8 → offset = 8-35 = -27
// → JMP_IF_FALSE는 0이어야 점프. goto는 PUSH 0, JMP_IF_FALSE offset
// [31]PUSH[32]0  [33]JMP_IF_FALSE[34]-27
// [35]LOAD[36]0  [37]PRINT  [38]HALT

let p6 = [
  0,0, 2,0,
  0,1, 2,1,
  1,1, 0,5, 13,
  7,8,
  11,
  1,0, 1,1, 3,
  2,0,
  1,1, 0,1, 3,
  2,1,
  0,0, 7,-27,
  1,0, 10, 11
]
let o6 = run_vm(p6)
let ok6 = check_arr("sum(1..5)", o6, [15])

