// PUSH 5, NEG, PRINT → -5
let p7 = [0,5, 12, 10, 11]
let o7 = run_vm(p7)
let ok7 = check_arr("NEG: -5", o7, [-5])

// 테스트 8: CMP_EQ
// PUSH 3, PUSH 3, CMP_EQ, PRINT → 1
let p8 = [0,3, 0,3, 9, 10, 11]
let o8 = run_vm(p8)
let ok8 = check_arr("3==3", o8, [1])

// 테스트 9: 다중 PRINT
// PUSH 1, PRINT, PUSH 2, PRINT, PUSH 3, PRINT, HALT
let p9 = [0,1, 10, 0,2, 10, 0,3, 10, 11]
let o9 = run_vm(p9)
let ok9 = check_arr("multi-print", o9, [1, 2, 3])

// 테스트 10: 복잡한 수식 (a=6, b=7, c=a*b)
// PUSH 6, STORE 0, PUSH 7, STORE 1
// LOAD 0, LOAD 1, MUL, STORE 2
// LOAD 2, PRINT, HALT
let p10 = [0,6, 2,0, 0,7, 2,1, 1,0, 1,1, 5, 2,2, 1,2, 10, 11]
let o10 = run_vm(p10)
