// [13,14]: JMPF body_ip (2칸)
// [15,16]: LOAD0 (sum) (2칸)
// [17]: PRINT
// [18]: HALT
// --- 본체 (ip=19) ---
// [19,20]: LOAD0 (sum)
// [21,22]: LOAD1 (i)
// [23]: ADD
// [24,25]: STORE0 (sum)
// [26,27]: LOAD1 (i)
// [28,29]: PUSH1
// [30]: ADD
// [31,32]: STORE1 (i)
// [33,34]: JMP 8 (체크로)
// 총 35칸
// JMPF addr = 19

let loop_prog = [
  0,0, 2,0,
  0,1, 2,1,
  1,1, 0,5, 11,
  8,19,
  1,0, 12, 14,
  1,0, 1,1, 3,
  2,0,
  1,1, 0,1, 3,
  2,1,
  7,8
]
