// x=5
// PUSH5 STORE0 LOAD0 PUSH0 CMP_GT
// JMPF else_addr
// PUSH1 JMP end_addr
// [else] PUSH2
// [end]  PRINT HALT
//
// [0]0,5  [2]2,0  [4]1,0  [6]0,0  [8]11
// [9]8,[10]17   JMPF 17 (x>0 거짓이면 else)
// [11]0,1       PUSH 1
// [13]7,[14]19  JMP 19 (end)
// [15]... 아, [11]0,[12]1  [13]7,[14]19  = 4칸 = ip 11~14
// [15,16]=PUSH2
// [17]=PRINT  HALT ... 아, JMPF가 17을 가리키면 거기가 PUSH2이어야
// 다시:
// [9]8,[10]15  JMPF 15
// [11]0,[12]1  PUSH1
// [13]7,[14]17 JMP 17
// [15]0,[16]2  PUSH2 (else)
// [17]12 PRINT  [18]14 HALT

let ok12 = check_arr("if 5>0: 1 else 2",
  run_vm([0,5, 2,0, 1,0, 0,0, 11,
          8,15, 0,1, 7,17, 0,2,
          12, 14]),
