// FreeLang v8 ML — Phase 10 자체 호스팅 증명 테스트
import { Interpreter } from '../src/runtime/interpreter';
import { Lexer } from '../src/lexer/lexer';
import { Parser } from '../src/parser/parser';
import * as fs from 'fs';
import * as path from 'path';

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function assertEqual<T>(a: T, b: T, msg?: string) {
  const m = msg ?? `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`;
  if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(m);
}

// FL8 소스 실행 → 마지막 표현식 결과
function runFL8(src: string): unknown {
  const interp = new Interpreter();
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  return interp.run(program);
}

// FL8 소스 실행 → 숫자 결과
function runNum(src: string): number {
  const result = runFL8(src) as any;
  if (result?.tag === 'number') return result.val;
  if (result?.tag === 'array') return result.val.map((v: any) => v.val);
  throw new Error(`숫자 아님: ${JSON.stringify(result)}`);
}

// FL8 소스 실행 → 배열 결과 (숫자)
function runArr(src: string): number[] {
  const result = runFL8(src) as any;
  if (result?.tag === 'array') return result.val.map((v: any) => v.val ?? v);
  if (result?.tag === 'number') return [result.val];
  throw new Error(`배열 아님: ${JSON.stringify(result?.tag)}`);
}

// .fl8 파일 로드
function loadFL8(filename: string): string {
  return fs.readFileSync(path.join(__dirname, '..', 'examples', filename), 'utf-8');
}

// .fl8 파일 → 인터프리터 + 추가 소스 실행
function runFL8File(filename: string, extra = ''): Interpreter {
  const src = loadFL8(filename) + '\n' + extra;
  const interp = new Interpreter();
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  interp.run(program);
  return interp;
}

// ============================================================
// 1. 렉서 자체 호스팅 (selfhost_lexer.fl8)
// ============================================================
console.log('\n── 렉서 자체 호스팅 ──');

const LEXER_SRC = loadFL8('selfhost_lexer.fl8');

test('렉서: "42 + x * 3" → [NUM,OP,IDENT,OP,NUM]=[1,3,2,3,1]', () => {
  const src = LEXER_SRC + `
tokenize([52, 50, 32, 43, 32, 120, 32, 42, 32, 51])
`;
  const result = runArr(src);
  assertEqual(result, [1, 3, 2, 3, 1]);
});

