// FreeLang v8 ML — Phase 11 REPL 테스트
// REPL 핵심 기능을 Interpreter를 통해 직접 테스트
// (readline TTY 환경 없이)

import { Interpreter, RuntimeValue } from "../src/runtime/interpreter";
import { Lexer } from "../src/lexer/lexer";
import { Parser } from "../src/parser/parser";
import { formatResult, isMultilineContinue } from "../src/repl/repl";

// ============================================================
// 테스트 프레임워크
// ============================================================

let passed = 0;
let failed = 0;
const failedNames: string[] = [];

function test(name: string, fn: () => void): void {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
    failedNames.push(name);
  }
}

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error(msg);
}

function assertEqual<T>(a: T, b: T, msg?: string): void {
  const ja = JSON.stringify(a);
  const jb = JSON.stringify(b);
  if (ja !== jb) throw new Error(msg ?? `expected ${jb}, got ${ja}`);
}

// ============================================================
// REPL 세션 시뮬레이터
// Interpreter 인스턴스를 유지하며 여러 번 runInGlobal() 호출
// ============================================================

function makeSession() {
  const interp = new Interpreter();

  function exec(src: string): RuntimeValue {
    const { tokens, errors: lexErr } = new Lexer(src).tokenize();
    if (lexErr.length > 0) throw new Error(`Lex: ${lexErr[0].message}`);
    const { program, errors: parseErr } = new Parser(tokens).parse();
    if (parseErr.length > 0) throw new Error(`Parse: ${parseErr[0].message}`);
    return interp.runInGlobal(program);
  }

  function getNames(): string[] {
    return interp.getGlobalNames();
  }

  return { exec, getNames, interp };
}

// ============================================================
// 1. 세션 지속성: 변수가 다음 실행에서도 유지
// ============================================================

console.log("\n[1] 세션 지속성 테스트");

test("변수 선언 후 다음 실행에서 참조 가능", () => {
  const { exec } = makeSession();
  exec("let x = 10");
  const rv = exec("x");
  assertEqual(rv, { tag: "number", val: 10 });
});

test("함수 선언 후 다음 실행에서 호출 가능", () => {
  const { exec } = makeSession();
  exec("fn double(n) { n * 2 }");
  const rv = exec("double(21)");
  assertEqual(rv, { tag: "number", val: 42 });
});

test("변수 재할당 반영됨", () => {
  const { exec } = makeSession();
  exec("let count = 0");
  exec("count = count + 1");
  exec("count = count + 1");
  const rv = exec("count");
  assertEqual(rv, { tag: "number", val: 2 });
});

test("여러 변수 독립 유지", () => {
  const { exec } = makeSession();
  exec("let a = 100");
  exec("let b = 200");
  const ra = exec("a");
  const rb = exec("b");
  assertEqual(ra, { tag: "number", val: 100 });
  assertEqual(rb, { tag: "number", val: 200 });
});

// ============================================================
// 2. 누적 실행: 여러 줄 순차 실행
// ============================================================

console.log("\n[2] 누적 실행 테스트");

test("순차 실행: a + b + c", () => {
  const { exec } = makeSession();
  exec("let a = 1");
  exec("let b = 2");
  exec("let c = 3");
  const rv = exec("a + b + c");
  assertEqual(rv, { tag: "number", val: 6 });
});

test("함수 정의 후 다른 함수에서 호출", () => {
  const { exec } = makeSession();
  exec("fn square(x) { x * x }");
  exec("fn sumOfSquares(a, b) { square(a) + square(b) }");
  const rv = exec("sumOfSquares(3, 4)");
  assertEqual(rv, { tag: "number", val: 25 });
});

test("배열 생성 후 조작", () => {
  const { exec } = makeSession();
  exec("let arr = [10, 20, 30]");
  const rv = exec("arr");
  assert(rv.tag === "array", "배열이어야 함");
  if (rv.tag === "array") {
    assertEqual(rv.val.length, 3);
  }
});

test("문자열 변수 지속", () => {
  const { exec } = makeSession();
  exec(`let greeting = "Hello, FreeLang!"`);
  const rv = exec("greeting");
  assertEqual(rv, { tag: "string", val: "Hello, FreeLang!" });
});

// ============================================================
// 3. 오류 회복: 오류 후에도 계속 실행
// ============================================================

console.log("\n[3] 오류 회복 테스트");

test("정의되지 않은 변수 오류 후 이전 변수 유지", () => {
  const { exec } = makeSession();
  exec("let safe = 99");
  // 오류 발생
  let errored = false;
  try { exec("undefinedVar"); } catch { errored = true; }
  assert(errored, "오류가 발생해야 함");
  // 이전 변수 여전히 유지
  const rv = exec("safe");
  assertEqual(rv, { tag: "number", val: 99 });
});

test("파서 오류 후에도 이전 함수 유지", () => {
  const { exec } = makeSession();
  exec("fn greet(name) { name }");
  let errored = false;
  try { exec("fn ??? {}"); } catch { errored = true; }
  assert(errored, "파서 오류가 발생해야 함");
  // 이전에 정의한 함수는 여전히 동작
  const rv = exec(`greet("world")`);
  assertEqual(rv, { tag: "string", val: "world" });
});

test("런타임 오류 후 새 변수 정의 가능", () => {
  const { exec } = makeSession();
  let errored = false;
  try { exec("1 / 0"); } catch { errored = true; }
  // 0나누기가 오류를 던지지 않을 수도 있음 (Infinity) — 다른 오류 케이스 사용
  try { exec("undeclared_xyz"); } catch { errored = true; }
  assert(errored, "오류가 발생해야 함");
  // 새 변수 정의 가능
  exec("let newVar = 42");
  const rv = exec("newVar");
  assertEqual(rv, { tag: "number", val: 42 });
});

// ============================================================
// 4. .vars 기능: getGlobalNames() 테스트
// ============================================================

console.log("\n[4] getGlobalNames() 테스트");

test("새 Interpreter에 내장 함수들 존재", () => {
  const { getNames } = makeSession();
  const names = getNames();
  assert(names.includes("print"), "print 내장 함수 있어야 함");
  assert(names.includes("sqrt"), "sqrt 내장 함수 있어야 함");
  assert(names.includes("abs"), "abs 내장 함수 있어야 함");
});

test("변수 선언 후 getGlobalNames에 포함", () => {
  const { exec, getNames } = makeSession();
  exec("let myVar = 123");
  const names = getNames();
  assert(names.includes("myVar"), "myVar가 목록에 있어야 함");
});

test("함수 선언 후 getGlobalNames에 포함", () => {
  const { exec, getNames } = makeSession();
  exec("fn myFunc(x) { x }");
  const names = getNames();
  assert(names.includes("myFunc"), "myFunc가 목록에 있어야 함");
});

test("여러 변수 모두 getGlobalNames에 포함", () => {
  const { exec, getNames } = makeSession();
  exec("let alpha = 1");
  exec("let beta = 2");
  exec("let gamma = 3");
  const names = getNames();
  assert(names.includes("alpha"), "alpha 있어야 함");
  assert(names.includes("beta"), "beta 있어야 함");
  assert(names.includes("gamma"), "gamma 있어야 함");
});

// ============================================================
// 5. 멀티라인 블록 감지 로직
// ============================================================

console.log("\n[5] isMultilineContinue() 테스트");

test("빈 버퍼 — 멀티라인 아님", () => {
  assert(!isMultilineContinue([]), "빈 버퍼는 멀티라인 아님");
});

test("단순 한 줄 — 멀티라인 아님", () => {
  assert(!isMultilineContinue(["let x = 10"]), "단순 줄은 멀티라인 아님");
});

test("{ 열기 — 멀티라인 계속", () => {
  assert(isMultilineContinue(["fn foo(x) {"]), "{ 열린 상태는 멀티라인");
});

test("{ 열고 } 닫기 — 멀티라인 완료", () => {
  assert(!isMultilineContinue(["fn foo(x) {", "  x * 2", "}"]), "완전히 닫힌 블록은 멀티라인 아님");
});

test("중첩 { } — 열린 상태", () => {
  assert(isMultilineContinue(["if (true) {", "  if (false) {"]), "중첩 { 두 개 열린 상태");
});

test("중첩 { } — 하나만 닫힌 상태", () => {
  assert(isMultilineContinue(["if (true) {", "  if (false) {", "  }"]), "하나만 닫힌 상태는 여전히 멀티라인");
});

test("중첩 { } — 모두 닫힌 상태", () => {
  assert(!isMultilineContinue(["if (true) {", "  if (false) {", "  }", "}"]), "모두 닫힌 상태");
});

test("문자열 내 { 무시", () => {
  // 문자열 안의 { 는 카운트 안 됨
  assert(!isMultilineContinue([`let s = "{ not a block }"`]), "문자열 내 중괄호 무시");
});

// ============================================================
// 6. 결과 포맷팅
// ============================================================

console.log("\n[6] formatResult() 테스트");

test("null → null 반환 (출력 생략)", () => {
  const r = formatResult({ tag: "null" });
  assertEqual(r, null);
});

test("정수 숫자 포맷", () => {
  const r = formatResult({ tag: "number", val: 42 });
  assertEqual(r, "42");
});

test("소수 숫자 포맷", () => {
  const r = formatResult({ tag: "number", val: 3.14 });
  assertEqual(r, "3.14");
});

test("true 포맷", () => {
  const r = formatResult({ tag: "bool", val: true });
  assertEqual(r, "true");
});

test("false 포맷", () => {
  const r = formatResult({ tag: "bool", val: false });
  assertEqual(r, "false");
});

test("문자열 포맷 — 따옴표 포함", () => {
  const r = formatResult({ tag: "string", val: "hello" });
  assertEqual(r, '"hello"');
});

test("배열 포맷", () => {
  const r = formatResult({
    tag: "array",
    val: [
      { tag: "number", val: 1 },
      { tag: "number", val: 2 },
      { tag: "number", val: 3 },
    ] as RuntimeValue[],
  });
  assertEqual(r, "[1, 2, 3]");
});

test("빈 배열 포맷", () => {
  const r = formatResult({ tag: "array", val: [] });
  assertEqual(r, "[]");
});

test("함수 포맷 — <fn(params)> 형식", () => {
  const r = formatResult({
    tag: "fn",
    params: ["a", "b"],
    body: [],
    closure: null as any,
  });
  assertEqual(r, "<fn(a, b)>");
